create table public.contact_discovery_tokens(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,kind text not null check(kind in('email','phone')),token text not null,created_at timestamptz not null default now(),unique(owner_id,kind,token)); create index contact_discovery_tokens_token_idx on public.contact_discovery_tokens(kind,token); alter table public.contact_discovery_tokens enable row level security; create policy contact_discovery_tokens_owner on public.contact_discovery_tokens for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid()); grant select,insert,update,delete on public.contact_discovery_tokens to authenticated; revoke all on public.contact_discovery_tokens from anon;